    Bug 1911775 - Windows 10: show the window top border with accent color in window border enabled. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D218813

diff --git a/mail/themes/windows/mail/mailWindow1.css b/mail/themes/windows/mail/mailWindow1.css
index 8bee0e2c447..f90f198fded 100644
--- a/mail/themes/windows/mail/mailWindow1.css
+++ b/mail/themes/windows/mail/mailWindow1.css
@@ -66,6 +66,14 @@ treechildren::-moz-tree-row(dummy, selected, focus) {
         color: AccentColorText;
       }
     }
+
+    :root[tabsintitlebar][sizemode="normal"] {
+      border-top: .5px solid ActiveBorder;
+
+      &:-moz-window-inactive {
+        border-top-color: InactiveBorder;
+      }
+    }
   }
 }

diff --git a/mail/themes/windows/mail/spacesToolbar.css b/mail/themes/windows/mail/spacesToolbar.css
index 4e155bf662e..448426bc931 100644
--- a/mail/themes/windows/mail/spacesToolbar.css
+++ b/mail/themes/windows/mail/spacesToolbar.css
@@ -3,3 +3,9 @@
  * file, You can obtain one at http://mozilla.org/MPL/2.0/. */

 @import url("chrome://messenger/skin/shared/spacesToolbar.css");
+
+@media (-moz-windows-accent-color-in-titlebar) {
+  :root[sizemode=normal][tabsintitlebar] #spacesToolbar {
+    margin-top: 1px;
+  }
+}
